        self.bank, self.bindings, self.queue = {}, [], []
        self.rendered = {}
        self.rx = bytearray()
        self.pending = None
        self.index = self.sequence = self.last_rx = self.last_sent = 0
        self.last_good = None
        self.next_poll = 0
        self.state, self.last_error = 'STARTING', ''
        self.status_target = None
        self.closed = False
        c = config
