# Canvas painters and page visibility.


def _td_paint_controls():
    with _td_batch():
        controls.fill(0, 0, 65, 6, " ", -1, -1)
        level.draw()
        level_text.draw()

_td_page_names_win = ["Main", "Details"]


def _td_show_win(name):
    with _td_batch():
        _td_apply_win(name)


def _td_apply_win(name):
    if name not in _td_page_names_win:
        raise ValueError("unknown page")
    heading.visible = name == "Main"
    reading.visible = name == "Main"
    connection.visible = name == "Main"
    setpoint.visible = name == "Main"
    output.visible = name == "Main"
    help.visible = name == "Main"
    _td_show_canvases(win, name)


def show_page(name, window=None):
    if window is None:
        window = win
    if window is win:
        return _td_show_win(name)
    raise ValueError("unknown window")

