_td_link.bind(output, {"direction":"readwrite","table":"co","address":1,"dataType":"u16","wordOrder":"high_first","gain":1,"offset":0,"decimals":0,"prefix":"","suffix":"","event":"change","action":"value","writeValue":1,"releaseValue":0,"min":0,"max":1,"initial":0}, "checkbox")
_td_link.bind(level, {"direction":"readwrite","table":"hr","address":2,"dataType":"u16","wordOrder":"high_first","gain":1,"offset":0,"decimals":0,"prefix":"","suffix":"","event":"change","action":"value","writeValue":1,"releaseValue":0,"min":0,"max":100,"initial":0}, "slider")
